import numpy as np
import secrets
import hashlib
import base64

def task_func(num, from_base, to_base, alphabet):
    if from_base < 2 or to_base < 2:
        raise ValueError("from_base and to_base must be at least 2")
    if not isinstance(num, str) or len(num) == 0:
        raise ValueError("num must be a non-empty string")
    if not isinstance(alphabet, str) or len(alphabet) != 64 or len(set(alphabet)) != 64:
        raise ValueError("alphabet must be a string of 64 unique characters")

    digit_chars = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz"
    if from_base > len(digit_chars) or to_base > len(digit_chars):
        raise ValueError("base too large to convert")

    if from_base <= 36:
        digit_map = {ch: idx for idx, ch in enumerate("0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ")}
        for idx, ch in enumerate("abcdefghijklmnopqrstuvwxyz", start=10):
            digit_map[ch] = idx
    else:
        digit_map = {ch: idx for idx, ch in enumerate(digit_chars)}

    value = 0
    for ch in num:
        if ch not in digit_map or digit_map[ch] >= from_base:
            raise ValueError("num contains invalid characters for the specified base")
        value = value * from_base + digit_map[ch]

    if value == 0:
        converted = "0"
    else:
        out_digits = digit_chars[:to_base]
        converted_parts = []
        while value > 0:
            value, rem = divmod(value, to_base)
            converted_parts.append(out_digits[rem])
        converted = "".join(reversed(converted_parts))

    salt = secrets.token_hex(16)
    payload = f"{converted}:{salt}".encode("utf-8")
    digest = hashlib.sha256(payload).digest()

